    {
      "element_id": "prisma_2020_6_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "We checked the reference lists of included studies and previous meta-analysis [15, 18] for additionally eligible studies.",
      "reason": "No backward/forward citation searching in a citation index or platform was reported."
