    {
      "element_id": "prisma_2020_6_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "Systematic literature searches of PubMed, EMBASE, Wanfang database and the Cochrane Central Register of Controlled Trials were conducted up to July 2016.",
      "reason": "No journals or conference proceedings were hand-searched per the reported methods."
    }
