{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "All studies used total effective rate as an outcome measure. Meanwhile, fifteen studies used the cured rate [29-33, 35-40, 42, 46-48] and one study used the course of cured patient [31] as an outcome measure. Only one RCT referred to adverse effects and/or complications during acupuncture [47].",
      "reason": "Outcome domains (total effective rate, cured rate, course of cured patient, adverse effects) are identifiable only from the Results section; they are not listed and defined in the Methods as required, and definitions of efficacy are not provided (the authors even note 'definitions of efficacy in different studies varied')."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No time frame or time points of outcome measurement are specified for any outcome domain in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not state whether all compatible results (measures, time points, analyses) within each outcome domain were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No methods for selecting which results to collect within outcome domains are described."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to outcome-domain inclusion, definitions, or importance during the review are reported with rationales."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No changes to processes for selecting results within outcome domains are reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "We defined total cure rate and total effective rate as our end-points.",
      "reason": "Primary outcomes (total effective rate and cured rate) are identified as end-points, but this appears in the Results rather than Methods and no rationale for their prioritisation is given."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "The following information was extracted: first author, publication year, study location, sample size, mean age, disease stage.",
      "reason": "The methods list some extracted variables (first author, publication year, study location, sample size, mean age, disease stage), but this list is incomplete relative to the data actually collected and used, e.g., acupuncture type, comparison interventions, efficacy assessment scales, therapy period, and outcomes shown in Table 1 and subgroup analyses (text_8, table_0, text_5). Variables are listed but not fully defined."
