    {
      "element_id": "prisma_2020_10b_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No tool or guidance used to determine which data items to collect is cited. The Cochrane Handbook is cited only for risk of bias assessment (text_4), not for selecting data items."
    }
  ],
  "confidence": 88
}

{
