      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No process for obtaining or confirming risk-of-bias information from study investigators is described."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools were used for risk-of-bias assessment; assessment was performed manually by two reviewers."
