{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "relative risk (RR) with 95% confidence intervals (CI) was considered as common measure of the association between acupuncture therapy and total effective rate or total cured rate",
      "reason": "The effect measure (RR with 95% CI) is explicitly specified for both outcomes (total effective rate and cured rate) used in the synthesis."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The heterogeneity interpretation thresholds (I2 categories) are reported, but no thresholds or ranges for interpreting the magnitude of effect sizes (e.g., small/moderate/large RR) are reported."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "relative risk (RR) with 95% confidence intervals (CI) was considered as common measure of the association",
      "reason": "RR is used throughout for all outcomes; no re-expression of results into another effect measure is described or needed, and no evidence suggests any re-expression was performed."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "RR is stated as the effect measure used, but no rationale or justification for choosing RR over other measures (e.g., odds ratio, risk difference) is provided."
    }
